macro_rules! deps {
    () => {
        ChallengeRef!();
        State!();
        ParamValue!();
    };
}

macro_rules! ChallengeParser {
    () => {
        deps!();
        # [doc = " Parses a list of challenges as in [RFC"] # [doc = " 7235](https://datatracker.ietf.org/doc/html/rfc7235) `Proxy-Authenticate`"] # [doc = " or `WWW-Authenticate` header values."] # [doc = ""] # [doc = " Most callers don't need to directly parse; see [`crate::PasswordClient`] instead."] # [doc = ""] # [doc = " This is an iterator that parses lazily, returning each challenge as soon as"] # [doc = " its end has been found. (Due to the grammar's ambiguous use of commas to"] # [doc = " separate both challenges and parameters, a challenge's end is found after"] # [doc = " parsing the *following* challenge's scheme name.) On encountering a syntax"] # [doc = " error, it yields `Some(Err(_))` and fuses: all subsequent calls to"] # [doc = " [`Iterator::next`] will return `None`."] # [doc = ""] # [doc = " See also the [`crate::parse_challenges`] convenience wrapper."] # [doc = ""] # [doc = " ## Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " use http_auth::{parser::ChallengeParser, ChallengeRef, ParamValue};"] # [doc = " let challenges = \"UnsupportedSchemeA, Basic realm=\\\"foo\\\", error error\";"] # [doc = " let mut parser = ChallengeParser::new(challenges);"] # [doc = " let c = parser.next().unwrap().unwrap();"] # [doc = " assert_eq!(c, ChallengeRef {"] # [doc = "     scheme: \"UnsupportedSchemeA\","] # [doc = "     params: vec![],"] # [doc = " });"] # [doc = " let c = parser.next().unwrap().unwrap();"] # [doc = " assert_eq!(c, ChallengeRef {"] # [doc = "     scheme: \"Basic\","] # [doc = "     params: vec![(\"realm\", ParamValue::try_from_escaped(\"foo\").unwrap())],"] # [doc = " });"] # [doc = " let c = parser.next().unwrap().unwrap_err();"] # [doc = " ```"] # [doc = ""] # [doc = " ## Implementation notes"] # [doc = ""] # [doc = " This rigorously matches the official ABNF grammar except as follows:"] # [doc = ""] # [doc = " *   Doesn't allow non-ASCII characters. [RFC 7235 Appendix"] # [doc = "     B](https://datatracker.ietf.org/doc/html/rfc7235#appendix-B) references"] # [doc = "     the `quoted-string` rule from [RFC 7230 section"] # [doc = "     3.2.6](https://datatracker.ietf.org/doc/html/rfc7230#section-3.2.6),"] # [doc = "     which allows these via `obs-text`, but the meaning is ill-defined in"] # [doc = "     the context of RFC 7235."] # [doc = " *   Doesn't allow `token68`, which as far as I know has never been and will"] # [doc = "     never be used in a `challenge`:"] # [doc = "     *   [RFC 2617](https://datatracker.ietf.org/doc/html/rfc2617) never"] # [doc = "         allowed `token68` for challenges."] # [doc = "     *   [RFC 7235 Appendix"] # [doc = "         A](https://datatracker.ietf.org/doc/html/rfc7235#appendix-A) says"] # [doc = "         `token68` \"was added for consistency with legacy authentication"] # [doc = "         schemes such as `Basic`\", but `Basic` only uses `token68` in"] # [doc = "         `credential`, not `challenge`."] # [doc = "     *   [RFC 7235 section"] # [doc = "         5.1.2](https://datatracker.ietf.org/doc/html/rfc7235#section-5.1.2)"] # [doc = "         says \"new schemes ought to use the `auth-param` syntax instead"] # [doc = "         [of `token68`], because otherwise future extensions will be"] # [doc = "         impossible.\""] # [doc = "     *   No scheme in the [registry](https://www.iana.org/assignments/http-authschemes/http-authschemes.xhtml)"] # [doc = "         uses `token68` challenges as of 2021-10-19."] pub struct ChallengeParser < 'i > { input : & 'i str , pos : usize , state : State < 'i > , }
    };
}

ChallengeParser!()